window.ANSWERS = {
dvt: {t:"Derin ven trombozu (DVT)", b:[
"Tanım: derin venlerde (genelde alt ekstremite) trombüs oluşumu. Etiyoloji = Virchow triadı: staz (immobilizasyon, uzun uçuş, gebelik), endotel hasarı (cerrahi, travma, kateter), hiperkoagülabilite (malignite, OKS, trombofili, nefrotik sendrom).",
"Risk: ameliyat, malignite (pankreas, kolorektal), obezite, yaş, gebelik/OKS, geçirilmiş DVT, FV Leiden.",
"Semptom: tek taraflı bacak şişliği, ağrı, ısı artışı, eritem, Homans (+), karşı bacağa göre çevre farkı >3 cm.",
"Tanı: Wells skoru → D-dimer → Doppler USG (ilk basamak, kompresyon+akım). Pelvik/IVC için BT/MR venografi; altın standart flebografi.",
"Tedavi: antikoagülasyon (DMAH/UFH → varfarin veya DOAK), en az 3 ay. İliofemoral masif olguda trombolitik/trombektomi; antikoagülan kontrendike ise vena kava filtresi.",
"Komplikasyon: PE, flegmazya seruleya dolens (venöz gangren), posttrombotik sendrom."]},
dvt_sinif: {t:"DVT sınıflaması ve tedavi endikasyonu", b:[
"Proksimal: popliteal ven ve üstü (popliteal, femoral, iliak, IVC) → mutlaka tedavi (PE riski yüksek).",
"Distal: popliteal altı (baldır venleri). Semptomatik, yayılım riski varsa (D-dimer yüksek, geniş, aktif kanser, immobil) tedavi; değilse 1-2 hafta USG takibi.",
"Süre: provoke olmuş ise 3 ay; provoke olmamış/kanser ise uzatılmış tedavi."]},
dvt_bilateral: {t:"İki bacakta ödem yapan hastalıklar / DVT iki bacakta olur mu", b:[
"Evet, bilateral DVT olabilir (IVC trombozu, iliofemoral yayılım).",
"Bilateral bacak ödemi: kalp yetmezliği, böbrek yetmezliği/nefrotik sendrom, siroz-hipoalbuminemi, kronik venöz yetmezlik, lenfödem, ilaç (CCB, steroid), hipotiroidi, IVC basısı/trombozu, gebelik."]},
doppler_bt: {t:"Doppler USG ve BT venografi farkı", b:[
"Doppler USG: ucuz, non-invaziv, radyasyonsuz, kompresyon + akım gösterir; bacak venleri için ilk seçenek. Operatöre bağımlı, pelvik venler/IVC zayıf görünür.",
"BT venografi: iliak, IVC, pelvik venleri ve PE'yi birlikte gösterir; kontrast + radyasyon, böbrek riski.",
"Altın standart: kontrastlı flebografi (nadiren kullanılır)."]},
dvt_foto: {t:"DVT fotoğrafı yorumu / tek taraflı bacak şişliği", b:[
"Gördüğüm: tek taraflı şişlik, gergin parlak deri, karşı bacakla çevre ölçüm farkı (fotoğraftaki rakamlar bacak çevre ölçüleri).",
"Ayırıcı: Baker kisti rüptürü, selülit, kas yırtığı/hematom, lenfödem, kronik venöz yetmezlik.",
"Tek taraflı şişlik yapan sendrom: Klippel-Trenaunay (kapiller malformasyon + varis + uzuv hipertrofisi), Parkes Weber (arteriovenöz malformasyon). AVM de bu tabloyu yapabilir."]},
dvt_proflaksi: {t:"DVT profilaksisi, Caprini skoru", b:[
"Risk skoru: Caprini (cerrahide). 0-1 çok düşük, 2 düşük, 3-4 orta, ≥5 yüksek risk.",
"Düşük: erken mobilizasyon. Orta/yüksek: DMAH (enoksaparin 40 mg sc 1x1) veya UFH 5000 U sc 2-3x1, operasyondan 12 saat önce/sonra başla; + mekanik (GCS, aralıklı pnömatik kompresyon).",
"Kanser cerrahisi, ortopedik majör cerrahi: 4 haftaya kadar uzat. Kanama riski yüksekse sadece mekanik."]},
pe: {t:"Pulmoner emboli (PE)", b:[
"Semptom: ani dispne, plöretik göğüs ağrısı, taşikardi, hemoptizi, senkop.",
"Tanı: klinik olasılık (Wells) → D-dimer (düşük olasılıkta) → BT pulmoner anjiyo (altın). EKG: sinüs taşikardisi, S1Q3T3. Grafi: normal olabilir; Westermark, Hampton hump.",
"Arter kan gazı: hipoksemi + hipokapni (solunumsal alkaloz), A-a gradienti artar. Eko: sağ ventrikül yüklenmesi.",
"COVID'den ayrım: D-dimer her ikisinde de artar; ayırt eden BT anjiyo (emboli), PCR, akciğer parankim bulgusu.",
"Tedavi: heparin (DMAH/UFH) → oral antikoagülan. Hemodinamik instabil (masif) → trombolitik, kontrendike ise cerrahi embolektomi/kateter."]},
mide_ca: {t:"Mide kanseri: tanım, risk, yayılım, evreleme, görüntüleme", b:[
"Çoğu adenokarsinom. Risk: H. pylori, atrofik gastrit, pernisiyöz anemi, tuzlu-nitrozaminli gıda, sigara, polip, aile öyküsü (CDH1), kan grubu A.",
"Klinik: epigastrik ağrı, erken doyma, kilo kaybı, anemi/melena, kitle. Tanı: endoskopi + biyopsi.",
"Yayılım: direkt (pankreas, kolon), lenfatik (D1-D2 istasyonları, Virchow), hematojen (karaciğer), peritoneal (Krukenberg, Blumer rafı, Sister Mary Joseph).",
"Evreleme (TNM): EUS (T ve N), BT toraks-abdomen-pelvis (M), laparoskopi ± periton lavajı, PET gerekirse. Lenf nodu: cerrahide en az 15 LN, D2 lenfadenektomi.",
"Tedavi: cerrahi (distal subtotal / total gastrektomi + D2) + perioperatif kemoterapi (FLOT). Erken evrede EMR/ESD."]},
mide_inop: {t:"Mide kanserinde inoperabilite kriterleri", b:[
"Uzak metastaz: karaciğer, peritoneal yayılım/asit, Krukenberg, Blumer rafı, Sister Mary Joseph nodülü, Virchow (sol supraklaviküler), Irish (sol aksiller) LN.",
"Lokal: aorta/çölyak/üst mezenterik damar sarılması, pankreas başı/kökü invazyonu, paraaortik LN (N3).",
"Genel: kaşeksi, kötü performans, ciddi komorbidite. (Şüphede: laparoskopi ile evreleme.)"]},
mide_yer: {t:"Mide tümörü yerine göre semptomlar", b:[
"Kardiya/proksimal: disfaji, retrosternal ağrı, reflü.",
"Korpus: epigastrik ağrı, erken doyma, kilo kaybı, anemi.",
"Antrum/pilor: bulantı-kusma, mide çıkış obstrüksiyonu."]},
mide_postop: {t:"Mide kanseri tanısı ve distal mide cerrahisi sonrası öneriler", b:[
"Tanı: üst GİS endoskopi + biyopsi, sonra evreleme.",
"Postop: demir emilimi bozulur (duodenum atlanır) → demir eksikliği anemisi; total gastrektomide B12 (intrinsik faktör) eksikliği → ömür boyu B12, Fe, Ca/D vit takibi.",
"Küçük, sık, kuru öğünler (dumping), alkalen reflü takibi, adjuvan tedavi ve düzenli onkolojik takip."]},
erken_mide: {t:"Erken evre mide kanseri", b:[
"Tanım: tümör mukoza veya submukozada (T1), LN tutulumundan bağımsız.",
"Endoskopik rezeksiyon (EMR/ESD) kriterleri: diferansiye, ≤2 cm, ülsersiz, mukoza sınırlı, LV invazyonu yok. Aksi halde cerrahi.",
"Prognoz çok iyi (5 yıl sağkalım >%90)."]},
krukenberg: {t:"Krukenberg tümörü / mide kaynaklı olduğunu nasıl anlarız", b:[
"Mide (nadiren kolon, meme) kaynaklı over metastazı; çoğu bilateral, solid.",
"Histoloji: müsin içeren taşlı yüzük hücreler (goblet/signet ring); immünohistokimya ile (CK7/CK20, CDX2) kökeni gösterilir.",
"Transselomik/hematojen-lenfojen yayılım. İnoperabilite işareti."]},
gastrektomi: {t:"Total gastrektomi komplikasyonları", b:[
"Erken: kanama, anastomoz kaçağı, duodenal güdük kaçağı (Billroth II), intraabdominal abse, pankreatit, pnömoni, damar yaralanması.",
"Aberran sol hepatik arter sol gastrik arterden çıkar (çölyak dalları: sol gastrik, splenik, ortak hepatik); lenfadenektomide yaralanma riski.",
"Geç: dumping, alkalen reflü, B12/demir eksikliği, kilo kaybı, anastomoz darlığı, afferent/efferent loop sendromu, osteoporoz."]},
dumping: {t:"Dumping sendromu", b:[
"Erken (yemekten 30 dk sonra): hiperozmolar içeriğin ince barsağa dökülmesi → sıvı kayması; karın ağrısı, ishal, çarpıntı, terleme, hipotansiyon.",
"Geç (1-3 saat): hızlı glukoz emilimi → hiperinsülinemi → reaktif hipoglisemi.",
"Tedavi: sık, küçük, proteinli, düşük karbonhidratlı öğün; sıvıyı yemekten ayır; akarboz, oktreotid; nadiren cerrahi."]},
bilroth: {t:"Billroth I – II", b:[
"Billroth I: distal gastrektomi + gastroduodenostomi (fizyolojik).",
"Billroth II: distal gastrektomi + gastrojejunostomi, duodenal güdük kapatılır. Komplikasyon: duodenal güdük kaçağı, afferent loop sendromu, alkalen reflü.",
"Roux-en-Y gastrojejunostomi: alkalen reflü en az."]},
antireflu: {t:"Antireflü mekanizmaları", b:[
"Gastroözofageal bileşke: alt özofagus sfinkteri (istirahat basıncı 10-30 mmHg), intraabdominal özofagus (karın içi pozitif basınç, aynı basınç ortamı), His açısı, diyafram krurası (pens etkisi), frenoözofageal ligaman, mukozal rozet/gastrik sling lifleri.",
"Özofagus: asit klirensi (peristaltizm, tükürük bikarbonatı).",
"Mide: normal gastrik rezervuar/boşalma (anormal rezervuar = reflüyü artırır).",
"Cerrahi: Nissen fundoplikasyonu (360°), Toupet (270°). GÖRH = reflü hastalığı."]},
barrett: {t:"Barrett özofagusu", b:[
"Kronik reflüye bağlı distal özofagus yassı epitelinin goblet hücreli intestinal (silendirik) epitele metaplazisi.",
"Özofagus adenokarsinom öncülü. Tanı endoskopi + biyopsi. Tedavi: PPI, takip endoskopisi; displazide ablasyon/EMR; yüksek dereceli displazi/kanserde özofajektomi."]},
yassi_epitel: {t:"Yassı epitel nerelerde var (ara sınav sorusu)", b:[
"Çok katlı yassı epitel: ağız, farinks, özofagus, anal kanal (dentat çizgi altı), vajina/ektoserviks, cilt (keratinize).",
"Tiroid foliküler epiteli tek katlı kübiktir. Barrett'te yassı → silendirik metaplazi."]},
fitik: {t:"Fıtık: tipleri, komplikasyonları, tedavi", b:[
"Tipler: inguinal (indirekt en sık, direkt), femoral, umbilikal, epigastrik, insizyonel, Spigel, obturator, lomber. En sık görülen: inguinal (indirekt) fıtık.",
"Komplikasyonlar: inkarserasyon (redükte olmaz), obstrüksiyon (ileus), strangülasyon (iskemi-nekroz), perforasyon.",
"Tedavi: cerrahi (mesh ile Lichtenstein, laparoskopik TEP/TAPP). Tek kesin tedavi cerrahidir; bandaj geçicidir."]},
fitik_ameliyat: {t:"Komplikasyonsuz fıtık neden opere edilir / obstrüksiyonda ne zaman ameliyat", b:[
"Spontan iyileşmez, zamanla büyür, inkarserasyon/strangülasyon riski vardır (özellikle femoral).",
"İnkarsere/obstrüktif fıtık: önce nazikçe manuel redüksiyon (analjezi, Trendelenburg), iskemi bulgusu yoksa. Redüksiyon başarısız veya strangülasyon (ağrı, ateş, lökositoz, deri eritemi, peritonit) → acil ameliyat; nekrotik barsak rezeke edilir.",
"Ameliyat: kese yüksek ligasyon, defekt onarımı + mesh (kontamine alanda mesh'ten kaçın)."]},
inguinal_kanal: {t:"İnguinal kanal anatomisi (katmanlar)", b:[
"Uzunluk 4-6 cm. Ön duvar: eksternal oblik aponevrozu (lateralde iç oblik de katılır). Arka duvar: transversalis fasyası (+ medialde conjoint tendon). Tavan: iç oblik ve transvers kas alt kenarı. Taban: inguinal ligaman.",
"Halkalar: derin (transversalis fasyası, inferior epigastrik damarların lateralinde), yüzeysel (eksternal oblik aponevrozu).",
"İçerik: erkekte spermatik kord, kadında round ligament; ilioinguinal sinir."]},
indirekt: {t:"İndirekt inguinal fıtık", b:[
"Derin halkadan girer (inferior epigastrik damarların lateralinden), kanalı boyunca ilerler, yüzeysel halkadan çıkar; skrotuma (kadında labium majusa) inebilir.",
"Konjenital (açık processus vaginalis), genç erkekte en sık. Kese kord yapılarının içinde.",
"Koruyucu mekanizmalar: oblik kanal, şutter mekanizması (iç oblik/transvers kasılması derin halkayı kapatır), transversalis fasyası, derin halka."]},
direkt_hess: {t:"Direkt fıtık ve Hesselbach üçgeni", b:[
"Hesselbach üçgeni sınırları: medial = rektus kılıfı lateral kenarı, lateral = inferior epigastrik damarlar, alt = inguinal ligaman.",
"Direkt fıtık: üçgenin zayıf transversalis fasyasından, edinsel, yaşlı erkek; skrotuma nadiren iner, genelde strangüle olmaz.",
"İndirekt-direkt ayrımı: inferior epigastrik damarlara göre (indirekt lateral, direkt medial)."]},
femoral: {t:"Femoral fıtık ve femoral kanal", b:[
"Femoral kanal sınırları: ön = inguinal ligaman, arka = pektineal (Cooper) ligaman, medial = lakünar (Gimbernat) ligaman, lateral = femoral ven.",
"Kadınlarda daha sık, inguinal ligamanın altında. İnkarserasyon ve strangülasyon riski en yüksek fıtık tipi → acil/erken onarım."]},
inkars: {t:"İnkarserasyon – strangülasyon farkı", b:[
"İnkarserasyon: içerik redükte olmaz, kan akımı korunur.",
"Strangülasyon: kan akımı bozulmuş (iskemi/nekroz): sürekli şiddetli ağrı, ateş, taşikardi, lökositoz, deride kızarıklık, ileus/peritonit → acil cerrahi.",
"Kadında inkarserasyon/strangülasyon, femoral fıtıkta daha sık."]},
hemoroid: {t:"Hemoroid", b:[
"Anal yastıklar (3-7-11 saat). Dentat çizgi üstü iç hemoroid (otonom, ağrısız, kanama), altı dış hemoroid (somatik, ağrılı).",
"Evreleme: 1 prolapsus yok, kanama; 2 defekasyonda çıkar kendiliğinden girer; 3 elle redükte; 4 redükte olmaz.",
"Tedavi: lif/sıvı, topikal; 1-3. derece bant ligasyonu; 3-4. derece hemoroidektomi (Milligan-Morgan, Ferguson).",
"Komplikasyon: tromboze hemoroid (sürekli ağrı, mor şişlik), kanama/anemi, strangülasyon. Ameliyat sonrası: idrar retansiyonu, kanama, stenoz, inkontinans."]},
fissur: {t:"Anal fissür (tipik ve atipik)", b:[
"Tipik: posterior midline (kadında anterior da olabilir). Defekasyonda yırtılma tarzı ağrı + parlak kırmızı kanama, sfinkter spazmı.",
"Kronik fissür triadı: fissür + sentinel pile (deri etiği) + hipertrofik anal papilla; iç sfinkter lifleri görünür.",
"Tedavi: lif, sıvı, sitz banyosu, topikal nitrogliserin %0.2 veya diltiazem %2; botulinum toksin; başarısızsa lateral internal sfinkterotomi.",
"Atipik (lateral, multipl, ağrısız, tedaviye dirençli): Crohn, TB, HIV, sifiliz, lösemi, malignite, CMV. Yaklaşım: EUA + biyopsi, kolonoskopi, kültür/serolojik tetkik."]},
anorektal: {t:"Anorektal anatomi", b:[
"Anal kanal ~4 cm. Dentat (pektinat) çizgi: üstü kolumnar epitel, otonom, venöz drenaj portal, lenf iç iliak/IMA; altı yassı epitel, somatik (pudendal), sistemik venöz, lenf inguinal.",
"İç sfinkter: düz kas, istemsiz. Dış sfinkter: çizgili, pudendal sinir. Puborektalis: anorektal açıyı sağlar.",
"Arter: superior rektal (IMA), orta rektal (iç iliak), inferior rektal (pudendal)."]},
uk_crohn: {t:"Ülseratif kolit – Crohn farkı (patoloji dahil)", b:[
"ÜK: rektumdan başlar, kontinü, sadece kolon (± backwash ileit), mukoza-submukoza; kriptit, kript apsesi, psödopolip; kanlı ishal; toksik megakolon; kolon ca riski yüksek; p-ANCA; sigara koruyucu; küratif tedavi total proktokolektomi.",
"Crohn: ağızdan anüse, en sık terminal ileum, skip lezyon, transmural, nonkazeifiye granülom, kaldırım taşı görünümü, fissür/fistül/striktür, perianal hastalık, kanlı olmayan ishal; ASCA; sigara kötüleştirir; cerrahi küratif değil (sınırlı rezeksiyon).",
"Biyopsi: ÜK'de kript apsesi/kript distorsiyonu, Crohn'da granülom + transmural inflamasyon."]},
uk_ekstra: {t:"ÜK ekstraintestinal (ekstramural) tutulum", b:[
"Eklem: periferik artrit, sakroiliit, ankilozan spondilit. Deri: eritema nodosum, piyoderma gangrenozum. Göz: üveit, episklerit.",
"Hepatobiliyer: primer sklerozan kolanjit (kolanjiokarsinom riski). Aftöz stomatit. Tromboemboli, amiloidoz."]},
apandisit: {t:"Akut apandisit", b:[
"Patogenez: lümen obstrüksiyonu (fekalit, lenfoid hiperplazi). Klasik: periumbilikal/epigastrik viseral ağrı + iştahsızlık/bulantı → ağrı sağ alt kadrana (McBurney) yerleşir; ateş, Rovsing, psoas, obturator, rebound/defans.",
"İlk 6-8 saat: künt periumbilikal ağrı, anoreksi, bulantı, hafif ateş; lokalize peritoneal bulgu henüz yok.",
"Tanı: klinik + Alvarado, lökositoz/CRP, USG (çocuk, kadın), BT.",
"Ayırıcı: mezenterik adenit, Meckel, Crohn, divertikülit, over torsiyonu/kist, EP, PID, üreter taşı, sağ piyelonefrit, akut kolesistit, gastroenterit.",
"Tedavi: apendektomi (laparoskopik) + antibiyotik. Komplikasyon: perforasyon, apse, plastron, peritonit, pylephlebitis, karaciğer absesi."]},
plastron: {t:"Plastron / neden hemen opere etmiyoruz", b:[
"Plastron: apendiks çevresinde omentum ve barsak ansları ile sarılmış inflamatuar kitle (sağ alt kadran kitlesi).",
"Hemen ameliyat edilmez: ödem/yapışıklık nedeniyle barsak yaralanması, fistül riski yüksek.",
"Tedavi: konservatif (antibiyotik, sıvı, takip); apse varsa perkütan drenaj; interval apendektomi 6-12 hafta sonra (yaşlıda ayrıca kolon kanseri dışlanır)."]},
pylephlebit: {t:"Pylephlebitis (pileflebit)", b:[
"Apendiks (veya divertikülit) kaynaklı septik tromboflebit: apendiküler/ileokolik ven → superior mezenterik ven → portal ven.",
"Klinik: yüksek ateş, titreme, sarılık, karaciğer apsesi. Tedavi: geniş spektrumlu antibiyotik + antikoagülasyon. Portal sistem yolu: apendiks → ileokolik ven → SMV → portal ven."]},
apandisit_ureter: {t:"Akut apandisit – üreter taşı ayrımı", b:[
"Üreter taşı: ani şiddetli kolik, yandan kasığa/genitale yayılım, hasta kıvranır, hematüri, ateş yok; USG/BT'de taş, idrarda eritrosit.",
"Apandisit: önce periumbilikal ağrı ve bulantı, sonra sağ alt kadran, hasta hareketsiz yatar, peritoneal bulgu, ateş, lökositoz, idrar temiz."]},
meme_kitle: {t:"Meme kitlesi yaklaşımı ve malignite bulguları", b:[
"Anamnez: yaş, menstrüel/HRT, aile öyküsü, hızlı büyüme, akıntı. Muayene: inspeksiyon, palpasyon (iki taraf), aksilla, supraklaviküler.",
"Malign: sert, düzensiz, sabit, ağrısız kitle; deri retraksiyonu, portakal kabuğu, meme başı çekintisi/kanlı akıntı, aksiller LAP.",
"Görüntüleme: <40 yaş USG; ≥40 yaş mamografi (+USG); yoğun/yüksek risk MR. Malign mamografi: spiküle kitle, kümelenmiş pleomorfik mikrokalsifikasyon, distorsiyon.",
"Üçlü değerlendirme: klinik + görüntüleme + patoloji. Biyopsi: İİAB (hücre; hızlı, reseptör bakılamaz) – kor biyopsi (doku; invaziv/in situ ayırır, ER/PR/HER2/Ki-67)."]},
meme_biyopsi: {t:"Meme biyopsi yöntemleri / tel işaretleme", b:[
"İİAB, kor (tru-cut) biyopsi, vakumlu biyopsi (USG veya stereotaksik), insizyonel/eksizyonel biyopsi.",
"Palpe edilemeyen lezyon: mamografi/USG eşliğinde tel (veya iğne) ile işaretleme, ardından eksizyon (lokalizasyon). Stereotaksi = mamografi kılavuzluğunda hedeflenmiş biyopsi/işaretleme."]},
meme_tarama: {t:"Meme kanseri tarama", b:[
"Türkiye (KETEM): 40-69 yaş her 2 yılda bir mamografi. Aylık kendi muayenesi (20+), 20-40 yaş klinik muayene.",
"<40 yaşta tarama amaçlı mamografi yeri yok; yüksek risk (BRCA) → erken yaş + MR + mamografi.",
"Mamografide kanser: spiküle kitle, kümelenmiş pleomorfik mikrokalsifikasyonlar (stereotipik küme, >5 kalsifikasyon), mimari distorsiyon."]},
kanser_tarama: {t:"Kanser tarama programları", b:[
"Meme: 40-69 yaş 2 yılda bir mamografi. Serviks: 30-65 yaş HPV DNA (5 yılda bir) ± smear. Kolorektal: 50-70 yaş gaitada gizli kan (FIT) 2 yılda bir; pozitif → kolonoskopi (veya 10 yılda bir kolonoskopi).",
"Prostat: 50 yaş (risk varsa 45), PSA ± rektal tuşe, bilgilendirilmiş karar. Akciğer: 50-80 yaş, ≥20 paket-yıl, yıllık düşük doz BT.",
"KRK taraması yaşı 50: insidans 50 sonrası artar, adenom-karsinom dizisi ~10 yıl sürer."]},
meme_risk: {t:"Meme kanseri risk faktörleri ve genetik", b:[
"Risk: kadın cinsiyet, yaş, erken menarş/geç menopoz, nulliparite/geç ilk doğum, HRT, obezite, alkol, göğüs radyasyonu, atipik hiperplazi/LCIS, 1. derece akraba öyküsü.",
"Genetik %5-10: BRCA1/2 (ömür boyu risk ~%70-80), TP53, PTEN, CDH1 (meme + diffüz mide kanseri), ATM, CHEK2, PALB2.",
"Genetik şüphe: <40 yaş, bilateral, erkek meme kanseri, meme+over, birden çok akraba. Otozomal dominant: anne ya da baba tarafı fark etmez.",
"BRCA taşıyıcısı: profilaktik bilateral mastektomi + salpingooferektomi, MR takibi."]},
meme_tedavi: {t:"Meme kanseri tipleri ve tedavi", b:[
"Duktal (en sık, kitle + mikrokalsifikasyon) vs lobüler (multisentrik/bilateral, E-kaderin kaybı, mamografide zor).",
"Moleküler: Luminal A (ER+/PR+, HER2-, Ki-67 düşük), Luminal B (Ki-67 yüksek ± HER2), HER2-zengin, triple negatif. Luminal A-B ayrımı Ki-67 ile (tedavi farkı kemoterapi gerekliliği).",
"Cerrahi: MKC + RT veya mastektomi + SLNB; adjuvan RT, kemoterapi, hormonal (tamoksifen / aromataz inh.), trastuzumab (HER2+).",
"Neoadjuvan endikasyonu: lokal ileri/inflamatuar, MKC'ye çevirmek (tümör/meme oranı yüksek), HER2+ ve triple negatif, N+ hastalık; yanıt prognostik.",
"Meme MR: BRCA/yüksek risk, lobüler ca, yoğun meme, ekstansif hastalık/multisentrisite, neoadjuvan yanıt, okült primer, implant."]},
meme_inop: {t:"Meme kanserinde inoperabilite kriterleri (Haagensen)", b:[
"Deri ödemi (portakal kabuğu) >1/3 meme, satellit deri nodülleri, inflamatuar kanser, göğüs duvarına fikse, kol ödemi.",
"Fikse/ >2.5 cm aksiller LN, supraklaviküler/internal mammaryen LN, uzak metastaz."]},
meme_cerrahi: {t:"Meme cerrahileri", b:[
"MKC (lumpektomi, kuadrantektomi) + RT; mastektomi (basit/total, modifiye radikal (Patey/Madden), cilt/meme başı koruyucu), radikal (Halsted, artık terk).",
"Aksilla: SLNB; pozitifse ALND (seçili olgu hariç). Rekonstrüksiyon (implant, TRAM/DIEP)."]},
mkc: {t:"Meme koruyucu cerrahi (MKC) kontrendikasyonları", b:[
"Multisentrik hastalık, yaygın malign mikrokalsifikasyon, tümör/meme oranı yüksek (kötü kozmetik), pozitif sınır ısrarı, inflamatuar kanser, hasta isteği.",
"RT verilemeyen: gebelik (1-2. trimester), önceki göğüs RT, aktif kolajen doku hastalığı (SLE, skleroderma). Genetik (BRCA/ATM/TP53) ve çok genç yaş: rölatif (DNA onarım defekti → ikincil malignite, lokal nüks).",
"Hasta mastektomi istiyorsa: sağkalım MKC+RT ile eşit, nüks oranı kabul edilebilir; hasta karar verir, ikna için bilgi vermek yeterli."]},
lcis_dcis: {t:"DCIS – LCIS ve invazyon", b:[
"DCIS: duktal, bazal membran içinde, öncül lezyon, mikrokalsifikasyon; tedavi MKC + RT ± tamoksifen veya mastektomi; SLNB mastektomi/ mikroinvazyon şüphesinde.",
"LCIS: neoplazi değil risk belirteci (bilateral), genelde tesadüfi; takip + kemoprevansiyon, pleomorfik tip eksize edilir.",
"İnvazyon: bazal membran aşılıp stromaya yayılım → invaziv karsinom."]},
sln: {t:"Sentinel LN, aksiller diseksiyon, aksilla anatomisi", b:[
"SLNB: tümörün ilk drene olduğu LN (mavi boya + Tc99 nanokolloid). Negatifse ALND gerekmez. Pozitifte: 1-2 pozitif + MKC + RT ise genelde ALND yok (Z0011), mastektomi/≥3 pozitifte ALND.",
"ALND komplikasyon: lenfödem (en önemli), seroma, n. torakodorsalis hasarı, n. torakalis longus hasarı (kanat skapula, serratus anterior), interkostobrakiyal sinir (üst kol medial uyuşma), omuz kısıtlılığı, enfeksiyon.",
"Kronik lenfödem 15-20 yıl sonra: Stewart-Treves sendromu (lenfanjiyosarkom).",
"Aksilla: ön pektoralis major-minör, arka subskapularis-teres major-latissimus; medial serratus anterior; içerik: aksiller arter/ven, brakiyal pleksus, LN seviye I-III (pektoralis minöre göre).",
"(Tiroid papiller ca'da 'santral LN' soruluyorsa: seviye VI diseksiyon, staj amaçlı)."]},
tiroid_nodul: {t:"Tiroid nodülüne yaklaşım, malignite bulguları, Bethesda", b:[
"Anamnez: radyasyon, aile (MTC/MEN), hızlı büyüme, ses kısıklığı, disfaji. FM: sert, sabit, LAP, trakeal deviasyon.",
"TSH ilk: düşük → sintigrafi (sıcak nodül nadiren malign); normal/yüksek → USG ± İİAB.",
"USG malignite: hipoekoik, mikrokalsifikasyon, düzensiz sınır, boyu>eni, intranodüler vaskülarite, ekstratiroidal uzanım, patolojik LN.",
"Bethesda: I yetersiz, II benign (0-3%), III AUS/FLUS (10-30%), IV foliküler neoplazi (25-40%), V şüpheli malign (50-75%), VI malign (97-99%). III tekrar İİAB/moleküler; IV lobektomi; V-VI cerrahi.",
"İİAB neden adenom–karsinom ayıramaz: ayrım kapsül ve damar invazyonuna dayanır; bu ancak tüm kapsülü içeren histopatolojide görülür (hücre morfolojisi yetmez)."]},
tiroid_ca: {t:"Tiroid kanserleri (sınıflama, tedavi, takip)", b:[
"Diferansiye: papiller (%80; lenfatik yayılım, Orphan Annie, psammoma, BRAF, iyi prognoz), foliküler (%10-15; hematojen, kapsül/damar invazyonu), Hürthle. TSH'ya bağımlı, RAI'ye duyarlı.",
"Medüller (%5): parafoliküler C hücresi, kalsitonin + CEA, RET, MEN2, amiloid; TSH bağımsız, RAI işe yaramaz. Anaplastik (%1-2): yaşlı, çok kötü prognoz.",
"Diferansiye tedavi: total/near total tiroidektomi (düşük risk küçük tümörde lobektomi) ± santral LN diseksiyonu; yüksek riskte RAI ablasyonu; levotiroksin ile TSH supresyonu.",
"Takip: tiroglobulin (+ anti-Tg), boyun USG. Medüller: total tiroidektomi + santral ± lateral LN; takip kalsitonin/CEA; önce feokromositoma dışla.",
"Boyun LN seviyeleri: I submental/submandibüler, II-IV juguler zincir (üst-orta-alt), V posterior üçgen, VI santral, VII üst mediasten. Papiller evreleme AJCC (yaş <55 / ≥55)."]},
tiroidektomi: {t:"Tiroidektomi komplikasyonları", b:[
"Hematom (boyun hematomu → solunum yolu obstrüksiyonu, acil açma), hipoparatiroidi/hipokalsemi, RLN hasarı, SLN dış dal hasarı, enfeksiyon, tiroid fırtınası, skar/keloid, trakeal yaralanma.",
"Tek taraflı RLN: ses kısıklığı; bilateral RLN: vokal kordlar medyan, stridor/solunum yolu tıkanması (nefes alamaz). Ses telini açan tek kas posterior krikoaritenoid.",
"SLN dış dal: krikotiroid kası, yüksek ses/ses yorgunluğu."]},
hipopara: {t:"Hipoparatiroidi/hipokalsemi bulguları", b:[
"Perioral/ekstremite parestezisi, kramp, tetani, laringospazm, QT uzaması.",
"Chvostek: fasiyal sinire vurunca yüz kaslarında seğirme. Trousseau: tansiyon manşonu ile karpal spazm.",
"Tedavi: IV kalsiyum glukonat, sonra oral Ca + aktif D vitamini."]},
graves: {t:"Graves hastalığı ve cerrahi", b:[
"Otoimmün (TSH reseptör antikoru), tirotoksikoz (kilo kaybı, çarpıntı, ısı intoleransı, terleme, tremor), diffüz guatr, oftalmopati (egzoftalmus, periorbital ödem, kemozis, diplopi), pretibial miksödem.",
"Tanı: TSH↓, sT4/sT3↑, TRAb, diffüz artmış tutulum. Tedavi: ATİ (metimazol/PTU), RAI, cerrahi (total tiroidektomi).",
"Cerrahi endikasyon: büyük guatr/basınç, malignite şüphesi, ATİ'ye uyumsuzluk/nüks, gebelik, aktif oftalmopati (RAI kötüleştirir). Ameliyat öncesi ötiroid yap (ATİ + Lugol/propranolol).",
"Cerrahi kontrendikasyon: dekompanse kalp/akciğer hastalığı, kontrolsüz tirotoksikoz."]},
hpt: {t:"Hiperparatiroidi ve hiperkalsemi", b:[
"Primer: adenom (%80-85), hiperplazi, karsinom (nadir); Ca↑ P↓ PTH↑. 'Taşlar (böbrek), kemikler (osteitis fibrosa, brown tümör), karın iniltileri (ülser, pankreatit), psişik inlemeler'.",
"Sekonder: KBY/D vit eksikliği (Ca düşük/normal, PTH↑). Tersiyer: uzun sekonder sonrası otonom hiperplazi (Ca↑, PTH↑).",
"Lokalizasyon: boyun USG + Tc99m sestamibi sintigrafisi. Tedavi: paratiroidektomi (adenom çıkarılır; hiperplazide 3.5 bez veya total + otogreft).",
"Hiperkalsemi nedenleri: primer HPT + malignite (en sık ikisi), granülomatöz hastalık, vit D fazlalığı, tiazid/lityum, immobilizasyon, tirotoksikoz."]},
feo: {t:"Feokromositoma", b:[
"Adrenal medulla tümörü; paroksismal HT, baş ağrısı, terleme, çarpıntı. Tanı: plazma/24 saatlik idrar metanefrin; görüntüleme BT/MR, MIBG sintigrafisi.",
"Tedavi: önce alfa blokaj (fenoksibenzamin), sonra beta blokaj, sonra adrenalektomi."]},
insidentaloma: {t:"Adrenal insidentaloma", b:[
"Tesadüfen saptanan ≥1 cm adrenal kitle. En sık nonfonksiyonel adenom; ayırıcı: ACC, feokromositoma, Conn, Cushing, metastaz, mielolipom, kist.",
"Değerlendirme: fonksiyon (deksametazon baskılama, aldosteron/renin, metanefrin), malignite (>4 cm, HU>10, heterojen, büyüme). Kanseri: adrenokortikal karsinom.",
"Cerrahi: fonksiyonel veya >4 cm/şüpheli kitle."]},
kolon_ca: {t:"Kolorektal kanser (genel)", b:[
"Adenom-karsinom dizisi: APC → KRAS → p53 (18q DCC) ~10 yıl. Risk: yaş, polip, ÜK/Crohn, aile, kırmızı et, obezite.",
"Sağ kolon: geniş lümen, ekzofitik kitle, anemi/okült kan, geç belirti. Sol kolon: dar lümen, anüler, obstrüksiyon, hematokezya, kalem gaita.",
"Tanı: kolonoskopi + biyopsi, CEA (takip), BT/MR. Tedavi: cerrahi (onkolojik rezeksiyon, LN), evre III/yüksek riskli II adjuvan kemoterapi."]},
kolon_yayilim: {t:"Kolon kanseri yayılım yolları", b:[
"Direkt (duvar, komşu organ), lenfojen (epikolik→paraaortik; sol kolon IMA zinciri), hematojen (portal ven → karaciğer en sık, sonra akciğer), transselomik/peritoneal (Douglas'ta Blumer rafı, over: Krukenberg), implantasyon (insizyon, port yeri)."]},
douglas: {t:"Douglas boşluğu", b:[
"Ayakta peritoneal kavitenin en derin yeri: kadında rektouterin (Douglas), erkekte rektovezikal boşluk.",
"Kolon/mide kanseri peritoneal metastazı burada toplanır: rektal tuşede sert, fikse raf = Blumer rafı."]},
kolon_met_kc: {t:"Kolon ca neden karaciğere metastaz yapar", b:[
"Yol: portal sistem (SMV/IMV → portal ven). Karaciğer ilk kapiller yatak.",
"Sağ lob daha sık: hacmi büyük, portal akımın büyük kısmını alır.",
"Karaciğer metastazı olan kolorektal: izole ise R0 rezeksiyon + kemoterapi (± RFA, portal ven embolizasyonu), aksi halde sistemik kemoterapi."]},
kolon_lenf: {t:"Sol kolon tümörü LN yayılımı ve lenfatik drenaj", b:[
"Sol kolon: epikolik → parakolik → intermediate (sol kolik, sigmoid dalları, IMA zinciri) → paraaortik LN.",
"İleri: torasik duktus yoluyla sol venöz açı → sol supraklaviküler LN (Virchow).",
"Meme/üst ekstremite lenfatik drenajı: aksiller LN (I-III) → subklavian trunk → sol torasik duktus / sağ lenfatik duktus. (Sol aksillaya drene = meme/kol, kolon değil.)"]},
ailesel: {t:"Herediter ve ailesel kolon kanserleri, FAP-Lynch", b:[
"FAP: APC (5q21-22), yüzlerce polip, 40 yaşa kadar neredeyse %100 kanser → profilaktik kolektomi. Lynch (HNPCC): mismatch repair genleri MLH1, MSH2, MSH6, PMS2, EPCAM; sağ kolon, genç yaş, Amsterdam kriterleri.",
"Herediter: bilinen germline mutasyon. Ailesel: kümelenme var, mutasyon yok; 1. derece akrabaya göre tarama 40 yaş veya akraba tanı yaşından 10 yıl önce.",
"FAP + MSS bulguları: Gardner (osteom, desmoid, dental, epidermoid kist), Turcot (beyin tümörü)."]},
endoskopi: {t:"Endoskopi ne işe yarar", b:[
"Tanı (görüntüleme + biyopsi), tedavi (polipektomi, EMR/ESD, kanama kontrolü, dilatasyon, stent, PEG), takip (Barrett, post-polipektomi), tarama (kolonoskopi), evreleme (EUS: T ve N)."]},
akut_arter: {t:"Akut arter tıkanıklığı", b:[
"Etiyoloji: emboli (kardiyak: AF, MI, kapak; en sık, femoral bifurkasyonda), tromboz (aterosklerotik zemin), travma, diseksiyon.",
"6P: pain, pallor, pulselessness, paresthesia, paralysis, poikilothermia. En tehlikeli bulgu: parestezi/paralizi (motor-duyu kaybı = acil tehdit), nabızsızlık değil.",
"Rutherford: I canlı, IIa marjinal tehdit, IIb acil tehdit, III geri dönüşümsüz. Kas 6 saat (4-6, en çok 6-12) iskemiye dayanır.",
"Tedavi: hemen heparin, acil revaskülarizasyon: Fogarty balon kateterle embolektomi (femoral arteriyotomi, lokal anestezi), trombolitik, bypass/endovasküler. Reperfüzyon: kompartman sendromu (fasiyotomi), hiperkalemi, rabdomiyoliz, ATN. Geri dönüşümsüzse amputasyon."]},
mezenter: {t:"Mezenterik iskemi (akut/kronik, NOMİ)", b:[
"Akut: SMA embolisi (en sık, AF), SMA trombozu (ateroskleroz), NOMİ (düşük debi/vazospazm; mortalite en yüksek), mezenterik ven trombozu.",
"Klinik: bulgudan orantısız şiddetli karın ağrısı, kusma, ishal; sonra peritonit, laktat↑, asidoz, lökositoz. Tanı: BT anjiyo (altın), DSA.",
"Tedavi: resüsitasyon, heparin, antibiyotik, embolektomi/bypass/stent, nekrotik barsak rezeksiyonu, second look. NOMİ: intraarteriyel papaverin.",
"Kronik (abdominal anjina): postprandiyal ağrı, 'yemek korkusu', kilo kaybı; ≥2 damar tıkalı; tedavi stent/bypass.",
"SMA besler: pankreatikoduodenal dalları, jejunum, ileum, çekum, apendiks, çıkan ve transvers kolonun proksimal 2/3'ü. (Distal 1/3 transvers → IMA.)",
"Tromboemboli riski: immobilite, kalp hastalığı, kanser (pankreas, kolorektal). Mezenterik iskemi diğer adı: abdominal anjina (kronik form)."]},
ima: {t:"IMA ve SMA beslenme alanı", b:[
"IMA: transvers kolonun distal 1/3'ü, splenik fleksura, inen kolon, sigmoid, rektumun üst kısmı (sol kolik, sigmoid, superior rektal).",
"SMA: duodenum 2-3-4. kısım, jejunum, ileum, çekum, apendiks, çıkan ve transvers kolonun proksimal 2/3'ü."]},
aort_dal: {t:"Abdominal aorta ve dalları, median arkuat ligaman sendromu", b:[
"Diyafram aortik hiatusundan (T12) girer, L4'te iliak communis'lere ayrılır. Çölyak (T12; sol gastrik, splenik, ortak hepatik), SMA (L1), renal (L1-L2), IMA (L3). Ayrıca inferior frenik, lomber, gonadal, orta sürrenal, median sakral.",
"Median arkuat ligaman sendromu: diyafram median arkuat ligamanının çölyak gövdeyi sıkıştırması; postprandiyal epigastrik ağrı, kilo kaybı, ekspiryumda daralma; tedavi ligaman serbestleştirme (laparoskopik)."]},
leriche: {t:"Leriche sendromu", b:[
"Aortoiliyak oklüzyon: klodikasyo (kalça/but/uyluk), femoral nabızların alınamaması, erkekte impotans.",
"Tedavi: aortobifemoral bypass veya endovasküler.",
"Anjiyoda tıkanıklık tarafında: femoral nabız alınamaz (kasık, inguinal ligaman altı, kasık kıvrımı ortasında alınır)."]},
pah: {t:"Periferik arter hastalığı, diyabetik ayak, ayakta ülser", b:[
"Semptom: intermitan klodikasyo, istirahat ağrısı, ülser, gangren. Fontaine: I asemptomatik, IIa >200 m klodikasyo, IIb <200 m, III istirahat ağrısı, IV doku kaybı.",
"Diyabetik ayak: nöropati + vasküler (krural damarlar: ön tibial, arka tibial, peroneal) + enfeksiyon.",
"Ayakta ülser ayırıcı: arteriyel (distal, ağrılı, nabız yok), venöz (malleol, nabız var, hiperpigmentasyon), nöropatik (basınç noktası, ağrısız), vaskülit, malignite (Marjolin)."]},
venoz: {t:"Kronik venöz yetmezlik, CEAP, safen venler", b:[
"CEAP: C0 yok, C1 telenjiektazi, C2 varis, C3 ödem, C4 cilt değişikliği (a pigmentasyon/egzama, b lipodermatoskleroz), C5 iyileşmiş ülser, C6 aktif ülser.",
"Venöz ülser patofizyoloji: kapak yetmezliği → ambulatuvar venöz hipertansiyon → kapiller geçirgenlik↑, fibrin manşet, lökosit tutulumu, doku hipoksisi → ülser. Tedavi: kompresyon, ablasyon/stripping.",
"Büyük safen: medial malleolden başlar, medial bacak-uyluk, safenofemoral bileşke; küçük safen: lateral malleolden arkaya, popliteal fossada popliteal vene açılır. Sefalik: kol lateral yüzeyi, deltopektoral oluktan aksiller vene.",
"Operasyon sonrası yara yeri enfeksiyonu: yüzeysel (cilt/ciltaltı), derin (fasya/kas), organ/boşluk; antibiyotik + drenaj."]},
yara_sinif: {t:"Cerrahi yara sınıflaması ve cerrahi alan enfeksiyonu", b:[
"Sınıf I temiz (GİS/solunum/ürogenital açılmadı), II temiz-kontamine (kontrollü açılma), III kontamine (akut inflamasyon, taşma, açık travma <4 saat), IV kirli/enfekte (perfore viskus, eski travma, apse).",
"Profilaksi: II (ve temiz+protez); III-IV tedavi edici antibiyotik.",
"SSI: yüzeysel, derin, organ/boşluk (30 gün; implantta 1 yıl)."]},
sirs: {t:"SIRS – sepsis – septik şok", b:[
"SIRS ≥2: T >38/<36, nabız >90, solunum >20 (veya PaCO2 <32), WBC >12000/<4000/>%10 bant.",
"Sepsis = enfeksiyon + organ disfonksiyonu (Sepsis-3: SOFA ≥2). Septik şok = yeterli sıvıya rağmen MAP ≥65 için vazopresör gereksinimi + laktat >2.",
"Enfeksiyon olmadan SIRS: pankreatit, travma, yanık, cerrahi, PE, iskemi-reperfüzyon, adrenal yetmezlik.",
"Tedavi: kültür + 1 saatte geniş spektrumlu antibiyotik, 30 ml/kg kristaloid, norepinefrin, odak kontrolü. Sepsis → MODS."]},
sok: {t:"Şok, mitokondri, ilk etkilenen organ", b:[
"Şok: doku perfüzyonunda yetersizlik/hücresel oksijen yetmezliği. Tipler: hipovolemik, kardiyojenik, obstrüktif, distribütif (septik, anafilaktik, nörojenik).",
"Hücre: oksijensiz mitokondride oksidatif fosforilasyon durur → ATP↓ → anaerobik glikoliz, laktik asidoz, Na/K ATPaz bozulur, hücre şişmesi, ölüm.",
"Önce splanknik dolaşım (barsak, böbrek, karaciğer) etkilenir; kalp-beyin korunur. Tedavi: ABC, 2 geniş damar yolu, sıvı/kan, vazopresör, etiyoloji.",
"ATLS hemorajik şok sınıfları: I <%15, II %15-30, III %30-40, IV >%40."]},
hipovol_damar: {t:"Hipovolemik şok yapan damar hastalıkları", b:[
"Ruptüre abdominal aort anevrizması, aort diseksiyonu/rüptürü, travmatik damar yaralanması, aortoenterik fistül, iliak/splenik arter anevrizması rüptürü, varis kanaması."]},
aort_anev: {t:"Aort anevrizması", b:[
"Tanım: çapın normalin ≥1.5 katı olması (abdominal aort >3 cm; normal ~2 cm, torasik ~3 cm). Çoğu infrarenal; risk: sigara, HT, ateroskleroz, erkek, yaş.",
"Klinik: pulsatil kitle; rüptür: karın/sırt ağrısı + pulsatil kitle + hipotansiyon. Tarama: USG.",
"Cerrahi: erkekte ≥5.5 cm (kadında 5.0), hızlı büyüme (>1 cm/yıl), semptomatik/rüptür → EVAR veya açık onarım.",
"Aort anevrizmasından ölen ünlü: Albert Einstein (AAA rüptürü)."]},
dsa: {t:"Dijital subtraksiyon anjiyografi (DSA)", b:[
"Kontrast verilip kontrastsız görüntü çıkarılır; sadece damarlar görünür. Giriş: femoral arter (Seldinger), kateter. Lokal anestezi ile yapılır, yatak istirahati.",
"Damarlar: abdominal aorta, iliak communis → interna/externa. Komplikasyonlar: giriş yeri hematom/psödoanevrizma, disseksiyon, emboli, anafilaksi, kontrast nefropatisi (kreatinin↑ 48-72 saat; önlem hidrasyon)."]},
antikoag: {t:"Antikoagülanlar (enoksaparin, heparin, varfarin, DOAK)", b:[
"UFH: aPTT ile takip, antidot protamin, HIT riski. DMAH (enoksaparin): ortalama MA ~4000-5000 Da, rutin takip gerekmez (renal yetmezlik/gebe/obezde anti-Xa), proflaksi 40 mg sc 1x1, tedavi 1 mg/kg 2x1.",
"Varfarin: K vit antagonisti, INR (hedef 2-3), antidot K vit/TDP. Fondaparinuks: anti-Xa. DOAK: rivaroksaban, apiksaban (Xa), dabigatran (trombin); rutin takip yok."]},
penetran: {t:"Silahlı/bıçaklı yaralanma, ameliyat endikasyonları", b:[
"ATLS: A (servikal) B C (kanama kontrolü, 2 geniş damar, kan) D E; FAST, grafi, BT (stabil).",
"Acil laparotomi: hemodinamik instabilite, peritonit, evisserasyon, serbest hava, GİS/idrar kanı. Ateşli silah karın: genelde laparotomi. Bıçak: stabil ve peritonit yoksa seri muayene/gözlem.",
"Epigastrik delici-kesici: kalp tamponadı (Beck triadı) düşün, subksifoid FAST/perikardiyal pencere.",
"Acil cerrahi gerekmeyen: stabil hastada sağ üst kadran (karaciğer) yaralanması, kendiliğinden duran kanama."]},
kunt_travma: {t:"Künt travma tetkikleri", b:[
"Stabilse: FAST + direkt grafiler (akciğer, pelvis) + kontrastlı BT. Instabil: FAST pozitifse laparotomi.",
"DPL (diagnostik periton lavajı): lavaj kateteri (peritoneal diyaliz tipi) ile sıvı alınır; kan (>10 ml), safra, barsak içeriği, eritrosit >100 000/mm³ pozitif."]},
travma_gen: {t:"Travmaya yaklaşım, altın saat", b:[
"Altın saat: travmadan sonraki ilk 1 saat; definitif tedavi bu sürede olmalı.",
"ATLS ABCDE: havayolu + servikal koruma, solunum, dolaşım/kanama, nörolojik (GKS), çıplak bırak (E). Grafi: servikal lateral, AP akciğer, AP pelvis; FAST; sonra BT."]},
dalak: {t:"Dalak yaralanması, Kehr belirtisi", b:[
"Künt travmada karaciğerle birlikte en sık yaralanan solid organ. AAST derece I-V.",
"Kehr belirtisi: sol omuza yayılan ağrı (diyafram irritasyonu, frenik sinir). Tanı: FAST + BT.",
"Stabil: nonoperatif (gözlem, embolizasyon). Instabil: splenektomi/splenorafi. Splenektomi sonrası OPSI → aşılar (pnömokok, meningokok, Hib), antibiyotik proflaksisi."]},
kc_tumor: {t:"Karaciğer benign kitleleri ve Kasabach-Merritt", b:[
"Benign: hemanjiom (en sık; çoğu tedavisiz; biyopsi yapılmaz), FNH (merkezi skar, tedavi gereksiz), hepatik adenom (OKS/anabolik steroid; rüptür riski, malign dönüşüm; β-katenin mutasyonu prognostik → cerrahi), basit kist, hidatik kist.",
"Malign: HCC, kolanjiokarsinom, metastaz.",
"Kasabach-Merritt: dev vasküler tümör içinde trombosit tutulması → trombositopeni + koagülopati; tedavi steroid/vinkristin/sirolimus, embolizasyon/rezeksiyon."]},
kc_met: {t:"Karaciğere metastaz yapan tümörler ve tedavi", b:[
"Kolorektal (en sık), pankreas, mide, meme, akciğer, melanom, NET.",
"Kolorektalde rezektabl metastaz: cerrahi rezeksiyon (+ kemoterapi, RFA). Mide metastazında genelde palyatif sistemik tedavi."]},
hcc: {t:"Hepatoselüler karsinom, aflatoksin, Child-Pugh, Milan", b:[
"Risk: siroz (HBV, HCV, alkol, NASH), aflatoksin B1 (Aspergillus flavus; nemli yer fıstığı/tahıl → p53 mutasyonu). AFP; tanı sirozda 4 fazlı BT/MR (arteriyel hiperenhansman + washout).",
"Child-Pugh: bilirubin, albümin, INR, asit, ensefalopati (A 5-6, B 7-9, C 10-15). Child A, tek lezyon, portal HT yok → rezeksiyon; Child C/uygun → transplantasyon.",
"Milan kriterleri: tek lezyon ≤5 cm veya ≤3 lezyon (her biri ≤3 cm), vasküler invazyon/ekstrahepatik yayılım yok.",
"Diğer: RFA/MWA, TACE, sorafenib/atezolizumab-bevacizumab."]},
pankreatit: {t:"Akut pankreatit", b:[
"Etiyoloji: safra taşı (en sık), alkol, hipertrigliseridemi (>1000), ERCP, ilaç, hiperkalsemi, travma, enfeksiyon (kabakulak), otoimmün, skorpiyon, idiyopatik.",
"Tanı (3'ten 2'si): epigastrik/kuşak tarzı ağrı, amilaz/lipaz >3x, BT/USG.",
"Skorlama: Ranson (giriş: yaş>55, WBC>16000, glukoz>200, LDH>350, AST>250 'GA LAW'; 48 saat: Hct↓>10, BUN↑, Ca<8, PaO2<60, baz açığı>4, sıvı sekestrasyonu>6L), APACHE II, BISAP, Glasgow-Imrie, Atlanta (hafif/orta/ağır). Ranson dışı: BISAP, APACHE II, Balthazar (BT).",
"BT'de pankreas içi/çevresi hava = enfekte nekroz → debridman (acil cerrahi/endoskopik, step-up) endikasyonu.",
"Tedavi: agresif sıvı (RL), analjezi, erken enteral beslenme, rutin profilaktik antibiyotik yok; safra pankreatitinde kolesistektomi."]},
pankreatit_aile: {t:"Yoğun bakımdaki akut pankreatit hastasının yakınlarına bilgilendirme", b:[
"Anlaşılır dille: pankreas iltihabı, çoğu hafif geçer ama bir kısmı ağır seyreder; risk yüksek, yoğun bakımda yakın takip.",
"Skor adı yerine anlaşılır parametreler: tansiyon, idrar çıkışı, bilinç, solunum, ateş, laboratuvar. Dürüst, empatik, belirsizliği açıkla; sürekli bilgilendir."]},
pankreas_ca: {t:"Pankreas kanseri (Steve Jobs)", b:[
"Duktal adenokarsinom (en sık, baş %65); risk: sigara, kronik pankreatit, DM, aile, BRCA, KRAS. Ağrısız sarılık + Courvoisier, kilo kaybı, Trousseau; CA 19-9; BT pankreas protokolü.",
"Tedavi: Whipple + adjuvan kemoterapi. Steve Jobs pankreatik nöroendokrin tümörden öldü (daha yavaş seyirli)."]},
net_kist: {t:"Pankreas NET ve kistik tümörleri", b:[
"Fonksiyonel NET: insülinoma (en sık, Whipple triadı, %90 benign, enükleasyon), gastrinoma (ZES, MEN1), VIPoma, glukagonoma, somatostatinoma. Tedavi rezeksiyon; rezeke edilemeyen: somatostatin analogları (oktreotid), PRRT, everolimus.",
"Kistik: psödokist, seröz kistadenom (benign), müsinöz kistik neoplazi (premalign), IPMN (ana kanal malign riski yüksek), solid psödopapiller neoplazi (genç kadın)."]},
ikiz: {t:"Tek yumurta ikizinde transplantasyon", b:[
"Böbrek nakli: izogreft, immünosüpresyon gerekmez.",
"Tip 1 DM için pankreas nakli: otoimmün hastalık tekrarlar (otoimmün yıkım) → immünosüpresyon gerekir."]},
kolesistit: {t:"Akut kolesistit (kalküloz–akalküloz, tedavi, ayırıcı)", b:[
"Sistik kanal obstrüksiyonu (taş %90-95). Klinik: sağ üst kadran ağrısı, ateş, bulantı, Murphy bulgusu (tek FM bulgusu). Lab: lökositoz/CRP. USG: taş, duvar >4 mm, perikolesistik sıvı. HIDA: görüntülenmeme. Tokyo kriterleri.",
"Tedavi: NPO, sıvı, analjezi, antibiyotik; erken (ilk 72 saat, ≤7 gün) laparoskopik kolesistektomi → 'soğutmaya' gerek yok. Kötü genel durum (yaşlı, yüksek risk) → perkütan kolesistostomi/drenaj, sonra elektif.",
"Komplikasyon: gangren, perforasyon, amfizematöz kolesistit (diyabetik, Clostridium), Mirizzi, safra taşı ileusu.",
"Akalküloz: kritik hasta (yoğun bakım, TPN, yanık, sepsis), safra stazı + iskemi; daha kötü seyirli (gangren/perforasyon), tedavi kolesistostomi/kolesistektomi.",
"Sağ üst kadran ağrısı ayırıcı: MI (EKG ile ekarte), pnömoni/plörezi, hepatit, peptik ülser/perforasyon, pankreatit, kolanjit, böbrek taşı, sağ piyelonefrit, apandisit.",
"Kolesistitle karışan: peptik ülser, kolanjit, pankreatit, hepatit, yüksek apandisit."]},
kolanjit: {t:"Charcot triadı / Reynolds pentadı", b:[
"Charcot: ateş-titreme + sarılık + sağ üst kadran ağrısı (akut kolanjit).",
"Reynolds: + hipotansiyon + mental konfüzyon (akut süpüratif kolanjit). Tedavi: antibiyotik, sıvı, acil safra yolu dekompresyonu (ERCP)."]},
safra_psk: {t:"İntrahepatik kolanjiokarsinom, safra yolları, PSK", b:[
"Kolanjiokarsinom risk: PSK, koledok kisti/Caroli, hepatolitiyazis, Clonorchis/Opisthorchis, siroz.",
"PSK: otoimmün, intra+ekstrahepatik safra yolu inflamasyon-fibrozis, boncuk dizisi (MRCP/ERCP), ÜK ile birliktelik, p-ANCA; siroza gider, tedavi karaciğer nakli."]},
ileus: {t:"İleus: tanım, sebepler, radyoloji, tedavi", b:[
"Tanım: barsak içeriğinin ilerleyememesi. Mekanik (dinamik) / paralitik (adinamik).",
"Mekanik nedenler: lümen içi (yabancı cisim: çocukta bozuk para/oyuncak, safra taşı, fekalit, bezoar, mekonyum), duvarda/intramural (Crohn striktürü, tümör, divertikülit, radyasyon, invajinasyon), dışarıdan/ekstramural (yapışıklık/brid, fıtık, volvulus, dış bası). En sık ince barsakta: yapışıklık, sonra fıtık, tümör. Kolonda: tümör, volvulus, divertikülit.",
"Kardinal bulgular: kolik karın ağrısı, bulantı-kusma, distansiyon, gaz-gaita çıkaramama.",
"Grafi: hava-sıvı seviyeleri; ince barsak: santral, valvülae conniventes; kalın barsak: periferik, haustra.",
"Strangülasyon: sürekli ağrı, ateş, taşikardi, lökositoz, laktat↑, peritonit → acil ameliyat. Tedavi: NG dekompresyon, sıvı-elektrolit, takip; komplike ise cerrahi."]},
paralitik: {t:"Paralitik ileus – mekanik ayrımı", b:[
"Paralitik: peristaltizm yok. Nedenler: postoperatif (en sık), peritonit, elektrolit (hipokalemi), opioid/antikolinerjik, retroperitoneal hematom, pankreatit, sepsis, spinal/omurga travması, metabolik (DM, üremi); kurşun zehirlenmesi 'spastik ileus' yapar.",
"Ayrım: mekanikte kolik ağrı + artmış, metalik bağırsak sesi, seviyelenme, distal kollaps; paralitikte sessiz karın, hafif ağrı, yaygın gaz."]},
agri_tipleri: {t:"Karın ağrısı tipleri ve örnekler", b:[
"Viseral: künt, kötü lokalize, hat boyunca. Foregut → epigastrik, midgut → periumbilikal, hindgut → suprapubik. Örnek: erken apandisit, ileus (kolik).",
"Somatik (parietal peritoneum): keskin, iyi lokalize, harekette artar. Örnek: perfore ülser, apandisit sağ alt kadran.",
"Yansıyan: kolesistit → sağ skapula, pankreatit → sırt, üreter taşı → kasık, dalak → sol omuz (Kehr)."]},
bls: {t:"Restoranda biri bayıldı", b:[
"Ortam güvenliği → yanıt kontrolü → yardım (112) + OED iste → solunum/nabız ≤10 sn. Yoksa 30:2 kompresyon (100-120/dk, 5-6 cm), OED. Varsa yan yatış, nedeni araştır (hipoglisemi, senkop, aspirasyon/Heimlich)."]},
divertikulit: {t:"Divertikülit", b:[
"Sigmoid en sık; yalancı divertikül; düşük lifli diyet. Klinik: sol alt kadran ağrısı, ateş, lökositoz, kabızlık.",
"Tanı: BT (oral/rektal kontrastlı). Akut atakta kolonoskopi yapma (perforasyon riski), 6 hafta sonra yap.",
"Hinchey: I perikolik abse/flegmon, II pelvik/uzak abse, III pürülan peritonit, IV fekal peritonit.",
"Tedavi: komplike olmayan antibiyotik (siprofloksasin+metronidazol), apse >4-5 cm perkütan drenaj, Hinchey III-IV Hartmann.",
"Ileus mekanizması: inflamatuar ödem, fibrozis-striktür, apse/plastron bası."]},
sol_alt: {t:"Sol alt kadran ağrısı sebepleri", b:[
"Divertikülit (en sık), ÜK, kolon kanseri, over kisti/torsiyonu, EP, PID, üreter taşı, inguinal fıtık, IBS, mezenterik adenit."]},
ust_gis: {t:"Üst GİS kanama (nedenler, yaklaşım, Sengstaken)", b:[
"Nedenler: peptik ülser (en sık; duodenum bulbusu), özofagus/mide varisleri, gastrit/erozyon (NSAİ, alkol), Mallory-Weiss, özofajit, tümör, Dieulafoy, aortoenterik fistül.",
"Stres ülseri: Curling (yanık), Cushing (kafa travması/beyin cerrahisi, asit↑). Tedavi PPI.",
"Belirti: hematemez (kahve telvesi/taze), melena (Treitz üstü). En sık kanayan bölge duodenum bulbusu.",
"Yaklaşım: ABC, 2 geniş damar yolu, kristaloid, kan (Hb<7), kan grubu/INR, IV PPI, 24 saat içinde endoskopi (adrenalin enjeksiyonu, klips, termal). Varis: terlipressin/oktreotid, seftriakson, bant ligasyonu/skleroterapi.",
"Sengstaken-Blakemore: üç lümenli (mide balonu, özofagus balonu, aspirasyon); tamponad, geçici (≤24 saat), sonra TIPS/endoskopi.",
"Primer profilaksi: beta bloker + bant."]},
hemobilia: {t:"Hemobilia", b:[
"Safra yollarına kanama. Quincke triadı: sağ üst kadran ağrısı, sarılık, GİS kanama (melena).",
"Neden: travma (en sık), iyatrojenik (biyopsi, PTK), tümör, anevrizma. Tanı anjiyo; tedavi embolizasyon."]},
alt_gis: {t:"Alt GİS kanama, melena-hematokezya", b:[
"Nedenler: divertikül (yaşlıda en sık), anjiodisplazi, hemoroid, polip/kanser, ÜK/Crohn, iskemik kolit, post-polipektomi, Meckel (çocuk).",
"Hematemez: kan kusma. Melena: siyah, katranımsı (Treitz üstü, sindirilmiş). Hematokezya: taze kırmızı kan (alt GİS veya masif üst GİS).",
"Yaklaşım: resüsitasyon, kolonoskopi, anjiyo/embolizasyon, cerrahi."]},
meckel: {t:"Meckel divertikülü", b:[
"Vitellointestinal kanal kalıntısı; 2'ler kuralı: %2, ileoçekal valvden 2 feet, 2 inç, 2 tip heterotopik mukoza (mide, pankreas), 2 yaş.",
"Komplikasyon: çocukta ağrısız rektal kanama (en sık); yetişkinde obstrüksiyon (en sık), divertikülit, perforasyon. Tanı Tc99m sintigrafisi; tedavi rezeksiyon."]},
grafi: {t:"Direkt karın grafisi yorumu", b:[
"Diyafram altı serbest hava: ayakta/lateral dekübit grafide diyafram kubbesi altında hilal şekli radyolüsen alan = perfore viskus (mide gaz odacığından farkı: mide gazı mide duvarı içinde hava-sıvı seviyesi gösterir, midenin içinde kalır).",
"İnce barsak tıkanıklığı: santral yerleşimli dilate ansalar, merdiven basamağı tarzı küçük hava-sıvı seviyeleri."]},
kolon_perf: {t:"Kolonda en sık perforasyon", b:[
"Sigmoid (divertikülit, tümör). Obstrüktif tümörde çekum (kapalı ağız mekanizması, Laplace yasası)."]},
fitik_siklik: {t:"En sık görülen fıtıklar", b:[
"İnguinal (en sık; indirekt) > femoral (kadında) > umbilikal > insizyonel (postop)."]},
apendiks_ca: {t:"En sık apendiks kanseri", b:[
"Karsinoid (nöroendokrin tümör), genelde uçta; <1 cm apendektomi yeterli, >2 cm sağ hemikolektomi. Müsinöz tümör → psödomiksoma peritonei."]},
kusma_asit: {t:"Kusmada asit-baz ve sıvı seçimi, yanıkta Ringer", b:[
"Hipokloremik hipokalemik metabolik alkaloz (HCl kaybı, volüm kaybı → aldosteron). Tedavi: izotonik salin + KCl (hipokalemi düzeltilir).",
"Ringer laktat: fizyolojik, K içerir, büyük hacimde %0.9 NaCl gibi hiperkloremik asidoza yol açmaz. Yanıkta Parkland: 4 ml/kg/%TVYA ilk 24 saat RL (yarısı ilk 8 saat)."]},
hiperkalemi: {t:"Hiperkalemi: klinik, EKG, tedavi", b:[
"K >5.5; kas güçsüzlüğü, parestezi, aritmi. EKG: yüksek sivri T, PR uzaması, P kaybı, QRS genişlemesi, sine-wave, VF/asistoli.",
"Tedavi: kalsiyum glukonat %10 10 ml (miyokard koruma), insülin + dekstroz, salbutamol, NaHCO3, furosemid, kayeksalat/patiromer, diyaliz.",
"Otopsi: kalp diyastolde durur (gevşek, dilate)."]},
hipokalemi: {t:"Hipokalemi yönetimi", b:[
"Neden: kusma, diüretik, ishal, alkaloz, hipomagnezemi. EKG: T düzleşmesi, U dalgası, ST çökmesi.",
"Tedavi: oral KCl; ağırsa IV (periferden ≤10 mEq/saat, santralden ≤20), monitör, Mg düzelt, nedeni tedavi."]},
yara_iyilesme: {t:"Yara iyileşmesi", b:[
"Hemostaz (vazokonstriksiyon → primer tıkaç trombosit, sekonder tıkaç fibrin), inflamasyon (nötrofil → makrofaj → lenfosit), proliferasyon (fibroblast, anjiyogenez, tip III kollajen, epitelizasyon, kontraksiyon), remodeling (tip III → tip I kollajen, 3 ay-1 yıl).",
"Tipler: primer, sekonder (granülasyonla), tersiyer (gecikmiş primer). Geciktiren: DM, malnütrisyon, steroid, enfeksiyon, sigara, hipoksi, yaş."]},
homeostaz: {t:"Homeostaz, pH ve tampon sistemleri", b:[
"Homeostaz: iç ortamın sabitliği (Claude Bernard 'milieu intérieur'; terimi Walter Cannon verdi). pH 7.35-7.45.",
"Tamponlar: bikarbonat (ekstraselüler), proteinler/hemoglobin (hücre içi), fosfat, amonyak. Akciğer (CO2, dakikalar), böbrek (H+ atımı, HCO3 geri emilimi, saat-gün)."]},
hemostaz: {t:"Primer-sekonder hemostaz, transfüzyon komplikasyonları", b:[
"Primer: damar kasılması + trombosit adezyonu (vWF-GPIb), agregasyon (fibrinojen-GPIIb/IIIa) → trombosit tıkacı. Sekonder: koagülasyon kaskadı (intrinsik, ekstrinsik, ortak) → fibrin ağı; fibrinoliz plazmin.",
"Transfüzyon komplikasyonları: akut hemolitik (ABO), febril non-hemolitik (en sık), alerjik/anafilaksi, TRALI, TACO, bakteriyel kontaminasyon. Masif transfüzyon: hipotermi, hipokalsemi (sitrat), hiperkalemi, asidoz, dilüsyonel koagülopati."]},
sivi_gunluk: {t:"Günlük GİS sıvı sekresyonu", b:[
"Tükürük ~1-1.5 L, mide ~2 L, safra ~0.5-1 L, pankreas ~1-1.5 L, ince barsak ~1-3 L; toplam yaklaşık 7-9 L/gün, çoğu emilir (dışkıda 100-200 ml)."]},
crush: {t:"Crush sendromu ve kompartman sendromu (depremde 2 gün enkaz)", b:[
"Ezilme → rabdomiyoliz: mioglobin, K↑, P↑, Ca↓, asidoz → ATN. Kurtarmada hemen agresif sıvı (1-1.5 L/saat), idrar alkalizasyonu, hiperkalemi tedavisi, diyaliz.",
"Kompartman: 6P, pasif gerilmede ağrı, basınç >30 mmHg (ΔP <30) → acil fasiyotomi. Canlılığı bozulmuş ekstremite: gangren → amputasyon.",
"Metabolik/endokrin: hiperkalemi, hiperfosfatemi, hipokalsemi, metabolik asidoz, miyoglobinüri/ARF."]},
hipernatremi: {t:"Hipernatremi", b:[
"Na >145: su kaybı (insensibl, DI, ishal, osmotik diürez) veya tuz fazlalığı. Klinik: susuzluk, konfüzyon, nöbet, koma.",
"Tedavi: hipovolemikse önce izotonik, sonra hipotonik/%5 dekstroz; Na düşüşü ≤10-12 mEq/gün (beyin ödemi). Serbest su açığı = 0.6×kg×(Na/140−1)."]},
hidatik: {t:"Kist hidatik (etken, yaşam döngüsü, eradikasyon)", b:[
"Echinococcus granulosus; son konak köpek, ara konak koyun, insan kaza ile. Yumurta (köpek dışkısı) → ağız → onkosfer → portal → karaciğer (%60-70), akciğer.",
"Kist: perikist, ektokist, endokist (germinal). Tanı USG/BT, serolojik testler. Tedavi: albendazol, PAIR, cerrahi (kistotomi + kapitonaj, hipertonik salin/H2O2; formalin/alkol sklerozan kolanjit yapar).",
"Komplikasyon: safra yolu rüptürü (kolanjit), peritona rüptür (anafilaksi, yayılım), enfeksiyon.",
"Eradikasyon: köpek taraması/praziquantel, mezbaha denetimi, sakatat köpeğe verilmemesi, hijyen, eğitim."]},
submandibuler: {t:"Submandibüler bölge şişliği sebepleri", b:[
"Sialolitiyazis/sialadenit (en sık), dental apse/Ludwig anjini, reaktif/enfeksiyöz LAP (TB), lenfoma, metastaz, tükürük bezi tümörü (pleomorfik adenom), ranula."]},
spastik_ileus: {t:"Spastik ileus", b:["Dinamik ileusun spastik tipi: kurşun zehirlenmesi, porfiri, ağır metaller."]},
obezite_cer: {t:"Obezite (bariatrik) cerrahisi", b:[
"Endikasyon: BMI ≥40 veya ≥35 + komorbidite.",
"Restriktif: sleeve gastrektomi (en sık), mide bandı. Malabsorptif: biliyopankreatik diversiyon / duodenal switch. Karma: Roux-en-Y gastrik bypass (altın standart).",
"Komplikasyon: staple hattı kaçağı, anastomoz darlığı, marginal ülser, internal herni, dumping, Fe/B12/Ca/vit D eksikliği, safra taşı, DVT/PE, GÖRH (sleeve).",
"Gastrik bypass en çok: tip 2 DM, HT, OSAS, dislipidemi düzeltir."]},
jinekomasti: {t:"Jinekomasti (fizyolojik durumlar)", b:[
"Fizyolojik: yenidoğan (maternal östrojen), puberte, yaşlı erkek. Patolojik: hipogonadizm, Klinefelter, siroz, hipertiroidi, tümör (testis/adrenal hCG), ilaçlar (spironolakton, simetidin, digoksin, ketokonazol), obezite."]},
nutcracker: {t:"Nutcracker sendromu", b:[
"Sol renal venin SMA ile aort arasında sıkışması; hematüri, sol yan ağrı, varikosel, pelvik konjesyon. Tanı Doppler/BT; tedavi konservatif, stent/transpozisyon."]},
karin_agri: {t:"Acile karın ağrısıyla gelen hastaya yaklaşım", b:[
"ABC, vitaller, kısa anamnez (başlangıç, lokalizasyon, yayılım, kusma, barsak alışkanlığı, jinekolojik/üriner).",
"Muayene: inspeksiyon, oskültasyon (ileus: artmış metalik ses; paralitik: yok), perküsyon, palpasyon (rebound, defans, Murphy, Rovsing), rektal tuşe.",
"Tetkik: hemogram, CRP, amilaz/lipaz, biyokimya, laktat, idrar, β-hCG; ayakta direkt grafi, USG, BT. Cerrahi gerekip gerekmediğine karar ver."]},
peptik: {t:"Peptik ülser ve komplikasyonları", b:[
"H. pylori ve NSAİ; en sık duodenum bulbusu ön duvarı; gastrik ülser biyopsi ister.",
"Komplikasyonlar: kanama (en sık; duodenum arka duvar → gastroduodenal arter), perforasyon (ön duvar → serbest hava, peritonit), penetrasyon (arka duvar → pankreas), pilor stenozu (fışkırır tarzda yemek kusma, hipokloremik hipokalemik metabolik alkaloz), malignite (gastrik).",
"Tedavi: PPI + H. pylori eradikasyonu; komplikasyonda endoskopik/cerrahi."]},
ince_bag_tumor: {t:"İnce barsak tümörleri neden az", b:[
"Hızlı geçiş (kısa kanserojen teması), sıvı içerik (dilüsyon), düşük bakteri yükü, alkali pH, yüksek IgA/lenfoid doku, hızlı epitel yenilenmesi, kanserojen metabolizmasını yapan enzimler."]},
kolon_polip: {t:"Polipten kanser gelişimi (adenom-karsinom)", b:[
"Normal mukoza → APC kaybı (adenom) → KRAS → DCC/SMAD4 (18q) → p53 → karsinom. ~10 yıl. Risk: villöz yapı, >1 cm, displazi."]},
cizim_portal: {t:"Portal sistem çizimi", b:[
"Portal ven = SMV + splenik ven birleşimi (pankreas boynu arkası, L1-L2). IMV splenik veya SMV'ye açılır; sol gastrik ven portal vene.",
"Portosistemik anastomozlar: özofagus (sol gastrik – azigos → varis), rektum (üst – orta/alt rektal → hemoroid), umbilikus (parumbilikal – epigastrik → caput medusae), retroperitoneal."]},
cizim_bacak: {t:"Bacak venleri çizimi", b:[
"Derin: ön/arka tibial + peroneal → popliteal → femoral (yüzeyel femoral + derin femoral) → ortak femoral → eksternal iliak.",
"Yüzeysel: büyük safen (medial malleol → safenofemoral bileşke), küçük safen (lateral malleol → popliteal fossa). Perforanlar: Cockett, Boyd, Dodd."]},
cizim_diger: {t:"Diğer çizim sorularından (safra yolu, kolon duvarı, 9 kadran, aort-bacak, mide-ince-kalın barsak damarları)", b:[
"Safra yolları: sağ/sol hepatik → ortak hepatik, sistik kanal → koledok → Vater ampullası.",
"Kolon duvarı: mukoza (epitel, lamina propria, muskularis mukoza), submukoza, muskularis propria (sirküler, longitudinal → tenia), subserosa, serosa.",
"9 kadran: iki dikey (midklaviküler) + iki yatay (subkostal, interspinal/transtüberküler) → hipokondriyum (2), epigastrik, lomber (2), umbilikal, iliak (2), hipogastrik.",
"Aorta → ortak iliak → eksternal iliak → femoral → popliteal → ön tibial + tibioperoneal gövde (arka tibial + peroneal); iç iliak ayrı.",
"SMA: inferior pankreatikoduodenal, jejunal/ileal, ileokolik, sağ kolik, orta kolik. IMA: sol kolik, sigmoid, superior rektal. Marginal (Drummond) arter, Riolan arkı. Çölyak: sol gastrik, splenik, ortak hepatik."]},
metabolik_asidoz: {t:"Metabolik asidoz yapan hastalıklar", b:[
"Anyon açığı yüksek (MUDPILES): metanol, üremi, DKA, propilen glikol, INH/demir, laktik asidoz (şok, sepsis, mezenterik iskemi), etilen glikol, salisilat.",
"Normal anyon açığı: ishal, RTA, pankreas fistülü, asetazolamid, hiperkloremi (salin).",
"Cerrahide laktik asidoz: mezenterik iskemi, perfore viskus/sepsis, şok."]}
};
